      let receivedError: Error | undefined;
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          receivedError = error;
        },
      };

      const orchestrator = createChatOrchestrator(
        createErrorProvider('"'"'string boom'"'"'),
        promptBuilder,
        undefined,
        {hooks}
      );
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('"'"'hello'"'"')));

      expect(outcome).toBe('"'"'string boom'"'"');
      expect(receivedError).toBeInstanceOf(Error);
      expect(receivedError?.message).toBe('"'"'string boom'"'"');
      expect(receivedError?.cause).toBe('"'"'string boom'"'"');
    });
' src/orchestration/chatOrchestrator.test.ts
